 30	pub(crate) const DEFAULT_JOURNAL_BYTES: u64 = 256 * 1024 * 1024;
 31	pub(crate) const DEFAULT_LEASE: Duration = Duration::from_secs(60);
 32	const PAGE_LIMIT: usize = 256;
 33	const MAX_LEASES: usize = 4096;
 34	const MAX_CHECKPOINT_BYTES: usize = 16 * 1024 * 1024;
