 36	const SCHEMA: &str = r#"
 37	CREATE TABLE IF NOT EXISTS session_projection_sessions (
 38	  epoch TEXT NOT NULL,
 39	  session_id TEXT NOT NULL,
 40	  latest_seq INTEGER NOT NULL DEFAULT 0,
 41	  checkpoint_seq INTEGER NOT NULL DEFAULT 0,
 42	  checkpoint_revision INTEGER NOT NULL DEFAULT 0,
 43	  checkpoint_json TEXT,
 44	  state_json TEXT NOT NULL,
 45	  PRIMARY KEY(epoch, session_id)
 46	);
 47	CREATE TABLE IF NOT EXISTS session_projection_events (
 48	  epoch TEXT NOT NULL,
 49	  session_id TEXT NOT NULL,
 50	  seq INTEGER NOT NULL,
 51	  source TEXT NOT NULL,
 52	  event_json TEXT NOT NULL,
 53	  encoded_bytes INTEGER NOT NULL,
 54	  created_ms INTEGER NOT NULL,
 55	  PRIMARY KEY(epoch, session_id, seq)
 56	);
 57	CREATE INDEX IF NOT EXISTS session_projection_events_age
 58	  ON session_projection_events(epoch, created_ms);
 59	"#;
