 61	#[derive(Debug, Clone, Serialize, Deserialize, Default)]
 62	struct FoldedState {
 63	    active_turn: Option<Value>,
 64	    last_turn_finished: Option<Value>,
 65	    model_rerouted: Option<Value>,
 66	    pending_permissions: BTreeMap<String, Value>,
 67	    components: BTreeMap<String, Value>,
 68	    browser_active: bool,
 69	}
