 81	    fn empty(revision: u64) -> Result<Self> {
 82	        Ok(Self {
 83	            latest: 0,
 84	            checkpoint_seq: 0,
 85	            checkpoint_revision: revision,
 86	            checkpoint_json: None,
 87	            state_json: serde_json::to_string(&FoldedState::default())?,
 88	        })
 89	    }
 90	}
 91	
 92	impl FoldedState {
 93	    fn wire(self) -> SessionProjectionState {
 94	        SessionProjectionState {
 95	            active_turn: self.active_turn,
 96	            last_turn_finished: self.last_turn_finished,
 97	            model_rerouted: self.model_rerouted,
 98	            pending_permissions: self.pending_permissions.into_values().collect(),
 99	            components: self.components.into_values().collect(),
100	            browser_active: self.browser_active,
101	        }
102	    }
103	
104	    fn fold_agent(&mut self, event: &AgentTurnEvent, value: &Value) {
105	        match event {
106	            AgentTurnEvent::TurnStarted { .. } => self.active_turn = Some(value.clone()),
107	            AgentTurnEvent::ModelRerouted { .. } => {
108	                self.model_rerouted = Some(value.clone());
109	            }
110	            AgentTurnEvent::TurnFinished { .. } => {
111	                self.active_turn = None;
112	                self.last_turn_finished = Some(value.clone());
113	                self.browser_active = false;
114	                self.pending_permissions.clear();
115	            }
116	            AgentTurnEvent::ComponentRender { component_id, .. } => {
117	                self.components.insert(component_id.clone(), value.clone());
118	            }
119	            AgentTurnEvent::ComponentUnmount { component_id, .. } => {
120	                self.components.remove(component_id);
121	            }
122	            AgentTurnEvent::BrowserActivity { active, .. } => self.browser_active = *active,
123	            _ => {}
124	        }
125	    }
126	
127	    fn fold_control(&mut self, envelope: &EventEnvelope, value: &Value) {
128	        match envelope.event {
129	            OceanEvent::PermissionRequest { .. } => {
130	                if let Some(permission_id) = envelope.permission_id {
131	                    self.pending_permissions
132	                        .insert(permission_id.to_string(), value.clone());
133	                }
134	            }
135	            OceanEvent::PermissionDecision { .. } => {
136	                if let Some(permission_id) = envelope.permission_id {
137	                    self.pending_permissions.remove(&permission_id.to_string());
138	                }
139	            }
140	            OceanEvent::Cancelled { .. } => {
141	                self.pending_permissions.clear();
142	            }
143	            _ => {}
144	        }
145	    }
146	}
