149	pub(crate) struct ProjectionCursor {
150	    epoch: String,
151	    session_hash: String,
152	    seq: u64,
153	}
154	
155	impl ProjectionCursor {
156	    fn new(epoch: &str, session_id: &str, seq: u64) -> Self {
157	        Self {
158	            epoch: epoch.to_string(),
159	            session_hash: session_hash(session_id),
160	            seq,
161	        }
162	    }
163	
164	    pub(crate) fn parse(raw: &str) -> std::result::Result<Self, ProjectionReset> {
165	        let mut parts = raw.split(':');
166	        if parts.next() != Some("sp1") {
167	            return Err(ProjectionReset::Malformed);
168	        }
169	        let (Some(epoch), Some(session_hash), Some(seq), None) =
170	            (parts.next(), parts.next(), parts.next(), parts.next())
171	        else {
172	            return Err(ProjectionReset::Malformed);
173	        };
174	        let seq = seq.parse().map_err(|_| ProjectionReset::Malformed)?;
175	        if Uuid::parse_str(epoch).is_err()
176	            || session_hash.len() != 16
177	            || !session_hash.bytes().all(|byte| byte.is_ascii_hexdigit())
178	        {
179	            return Err(ProjectionReset::Malformed);
180	        }
181	        Ok(Self {
182	            epoch: epoch.to_string(),
183	            session_hash: session_hash.to_string(),
184	            seq,
185	        })
186	    }
187	}
188	
189	impl std::fmt::Display for ProjectionCursor {
190	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
191	        write!(f, "sp1:{}:{}:{}", self.epoch, self.session_hash, self.seq)
192	    }
193	}
