196	pub(crate) enum ProjectionReset {
197	    Malformed,
198	    WrongEpoch,
199	    WrongSession,
200	    Future,
201	    Retention,
202	    Faulted,
203	    RevisionMismatch,
204	    InvalidLease,
205	    ExpiredLease,
206	    LeaseSessionMismatch,
207	}
208	
209	impl ProjectionReset {
210	    pub(crate) fn reason(self) -> &'static str {
211	        match self {
212	            Self::Malformed => "malformed_cursor",
213	            Self::WrongEpoch => "daemon_epoch_changed",
214	            Self::WrongSession => "session_mismatch",
215	            Self::Future => "future_cursor",
216	            Self::Retention => "retention_boundary",
217	            Self::Faulted => "projection_store_fault",
218	            Self::RevisionMismatch => "snapshot_revision_not_ready",
219	            Self::InvalidLease => "invalid_lease",
220	            Self::ExpiredLease => "expired_lease",
221	            Self::LeaseSessionMismatch => "lease_session_mismatch",
222	        }
223	    }
224	}
