227	pub(crate) struct SessionProjectionStore {
228	    db: Arc<Mutex<Connection>>,
229	    epoch: Arc<str>,
230	    wakes: broadcast::Sender<String>,
231	    leases: Arc<Mutex<HashMap<String, Lease>>>,
232	    faults: Arc<Mutex<HashSet<String>>>,
233	    logical_bytes: Arc<AtomicU64>,
234	    budget_bytes: u64,
235	    lease_duration: Duration,
236	}
237	
238	#[derive(Clone)]
239	struct Lease {
240	    session_id: String,
241	    min_seq: u64,
242	    expires: Instant,
243	}
244	
245	impl SessionProjectionStore {
246	    pub(crate) fn open(path: &Path) -> Result<Self> {
247	        let budget_bytes = std::env::var("OCEAN_SESSION_PROJECTION_JOURNAL_BYTES")
248	            .ok()
249	            .and_then(|raw| raw.parse::<u64>().ok())
250	            .filter(|value| *value > 0)
251	            .unwrap_or(DEFAULT_JOURNAL_BYTES);
252	        Self::open_with_config(path, budget_bytes, DEFAULT_LEASE)
253	    }
254	
255	    fn open_with_config(path: &Path, budget_bytes: u64, lease_duration: Duration) -> Result<Self> {
256	        if let Some(parent) = path.parent() {
257	            std::fs::create_dir_all(parent).with_context(|| {
258	                format!("creating projection DB directory {}", parent.display())
259	            })?;
260	        }

