+async fn send_projection_sse(
+    tx: &mpsc::Sender<Result<Event, Infallible>>,
+    shutdown: &CancellationToken,
+    event: Event,
+) -> bool {
+    tokio::select! {
+        biased;
+        _ = shutdown.cancelled() => false,
+        _ = tx.closed() => false,
+        result = tx.send(Ok(event)) => result.is_ok(),
+    }
+}
