+/// Durable session-projection SSE tail. SQLite is authoritative; the broadcast
+/// receiver is only a wake hint. Subscribe-before-page plus paging on lag closes
+/// the snapshot/live seam without depending on the legacy UUID replay ring.
+async fn session_projection_events(
+    State(state): State<AppState>,
+    Query(query): Query<SessionProjectionEventsQuery>,
+) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
+    let (tx, rx) = mpsc::channel(64);
+    let shutdown = state.shutdown.clone();
+    let stream_shutdown = state.shutdown.clone();
+    let session_id = query.session_id.to_string();
+    let mut cursor = query.after_cursor;
+    let lease_id = query.lease_id;
+    let projection = state.agent_events.projection();
+
+    tokio::spawn(async move {
+        let Some(store) = projection else {
+            let data = json!({ "type": "projection_reset", "reason": "projection_unavailable" })
+                .to_string();
+            let _ = send_projection_sse(
+                &tx,
+                &shutdown,
+                Event::default().event("projection_reset").data(data),
+            )
+            .await;
+            return;
+        };
+
+        // Register before the first durable page. Any append racing the query is
+        // either visible in SQLite or leaves a buffered wake that causes re-page.
+        // Idle tails re-page before lease expiry; page_after is the only renewal
+        // authority, so an abandoned reader cannot keep a lease alive.
+        let mut wakes = store.subscribe();
+        let lease_renew_interval = store.lease_renew_interval();
+        loop {
+            match store.page_after(&session_id, &cursor, &lease_id) {
+                Ok(frames) if !frames.is_empty() => {
+                    for frame in frames {
+                        cursor = frame.cursor.clone();
+                        let data = serde_json::to_string(&frame).unwrap_or_else(|_| {
+                            json!({ "type": "projection_reset", "reason": "serialize_failed" })
+                                .to_string()
+                        });
+                        if !send_projection_sse(
+                            &tx,
+                            &shutdown,
+                            Event::default()
+                                .id(frame.cursor)
+                                .event("session_projection")
+                                .data(data),
+                        )
+                        .await
+                        {
+                            return;
+                        }
+                    }
+                    continue;
+                }
+                Ok(_) => {}
+                Err(reset) => {
+                    let data = json!({
+                        "type": "projection_reset",
+                        "reason": reset.reason(),
+                    })
+                    .to_string();
+                    let _ = send_projection_sse(
+                        &tx,
+                        &shutdown,
+                        Event::default().event("projection_reset").data(data),
+                    )
+                    .await;
+                    return;
+                }
+            }
