255	    fn open_with_config(path: &Path, budget_bytes: u64, lease_duration: Duration) -> Result<Self> {
256	        if let Some(parent) = path.parent() {
257	            std::fs::create_dir_all(parent).with_context(|| {
258	                format!("creating projection DB directory {}", parent.display())
259	            })?;
260	        }
261	        let db = Connection::open(path)
262	            .with_context(|| format!("opening session projection DB {}", path.display()))?;
263	        #[cfg(unix)]
264	        {
265	            use std::os::unix::fs::PermissionsExt;
266	            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600))
267	                .with_context(|| format!("securing session projection DB {}", path.display()))?;
268	        }
269	        db.execute_batch(
270	            "PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL; PRAGMA foreign_keys=ON;",
271	        )?;
272	        db.execute_batch(SCHEMA)?;
273	        let logical_bytes = db.query_row(
274	            "SELECT COALESCE(SUM(encoded_bytes),0) FROM session_projection_events",
275	            [],
276	            |row| row.get::<_, u64>(0),
277	        )?;
278	        let (wakes, _) = broadcast::channel(1024);
