366	        fold(&mut state, &event);
367	        let state_json = serde_json::to_string(&state)?;
368	        tx.execute(
369	            "INSERT INTO session_projection_events(epoch,session_id,seq,source,event_json,encoded_bytes,created_ms) VALUES(?1,?2,?3,?4,?5,?6,?7)",
370	            params![&*self.epoch, session_id, seq, source_name(source), event_json, event_json.len() as u64, created_ms],
371	        )?;
