373	            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,state_json) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET latest_seq=excluded.latest_seq,state_json=excluded.state_json",
374	            params![&*self.epoch, session_id, seq, row.checkpoint_seq, row.checkpoint_revision, state_json],
375	        )?;
376	        tx.commit()?;
377	        drop(db);
378	        self.logical_bytes
379	            .fetch_add(event_json.len() as u64, Ordering::Relaxed);
380	        let cursor = ProjectionCursor::new(&self.epoch, session_id, seq);
381	        let _ = self.wakes.send(session_id.to_string());
382	        // Ordinary appends only trigger pressure compaction; age-based
383	        // checkpoint compaction runs when a persistence boundary advances.
384	        if self.logical_bytes.load(Ordering::Relaxed) > self.budget_bytes {
385	            self.compact(true)?;
386	        }
387	        Ok(cursor)
