390	    pub(crate) fn checkpoint(
391	        &self,
392	        session_id: &str,
393	        revision: u64,
394	        snapshot: Value,
395	    ) -> Result<Option<ProjectionCursor>> {
396	        let object = snapshot
397	            .as_object()
398	            .context("projection checkpoint must be an object")?;
399	        anyhow::ensure!(
400	            object.get("type").and_then(Value::as_str) == Some("projection_checkpoint")
401	                && object.get("persistence_revision").and_then(Value::as_u64) == Some(revision)
402	                && object.contains_key("transcript")
403	                && object.contains_key("tool_context")
404	                && object.len() == 4,
405	            "projection checkpoint is not normalized"
406	        );
407	        let event_json = serde_json::to_string(&snapshot)?;
408	        anyhow::ensure!(
409	            event_json.len() <= MAX_CHECKPOINT_BYTES,
410	            "projection checkpoint exceeds {MAX_CHECKPOINT_BYTES} bytes"
411	        );
412	        let created_ms = now_ms();
413	        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
414	        let tx = db.transaction()?;
415	        let row = load_row(&tx, &self.epoch, session_id)?.unwrap_or(SessionRow::empty(0)?);
416	        if revision < row.checkpoint_revision {
417	            anyhow::bail!("session projection checkpoint revision regressed");
418	        }
419	        if revision == row.checkpoint_revision && row.checkpoint_json.is_some() {
420	            return Ok(None);
421	        }
422	        let seq = row
423	            .latest
424	            .checked_add(1)
425	            .context("session projection cursor exhausted")?;
426	        tx.execute(
427	            "INSERT INTO session_projection_events(epoch,session_id,seq,source,event_json,encoded_bytes,created_ms) VALUES(?1,?2,?3,'checkpoint',?4,?5,?6)",
428	            params![&*self.epoch, session_id, seq, event_json, event_json.len() as u64, created_ms],
429	        )?;
430	        tx.execute(
431	            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,checkpoint_json,state_json) VALUES(?1,?2,?3,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET latest_seq=excluded.latest_seq,checkpoint_seq=excluded.checkpoint_seq,checkpoint_revision=excluded.checkpoint_revision,checkpoint_json=excluded.checkpoint_json",
432	            params![&*self.epoch, session_id, seq, revision, event_json, row.state_json],
433	        )?;
434	        tx.commit()?;
435	        drop(db);
436	        self.logical_bytes
437	            .fetch_add(event_json.len() as u64, Ordering::Relaxed);
438	        let cursor = ProjectionCursor::new(&self.epoch, session_id, seq);
439	        let _ = self.wakes.send(session_id.to_string());
440	        self.compact(false)?;
441	        Ok(Some(cursor))
442	    }
