444	    pub(crate) fn snapshot(
445	        &self,
446	        session_id: &str,
447	        file_revision: u64,
448	        file_snapshot: Value,
449	    ) -> std::result::Result<SessionProjection, ProjectionReset> {
450	        if self.is_faulted(session_id) {
451	            return Err(ProjectionReset::Faulted);
452	        }
453	
454	        // Inspect alignment first. A missing/older idle row is repaired only by
455	        // appending the same visible replacement frame live clients consume —
456	        // never by silently advancing checkpoint_seq over unrepresented rows.
457	        let needs_checkpoint = {
458	            let db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
459	            match load_row(&db, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)? {
460	                None => true,
461	                Some(row) => {
462	                    let state: FoldedState = serde_json::from_str(&row.state_json)
463	                        .map_err(|_| ProjectionReset::Faulted)?;
464	                    if file_revision < row.checkpoint_revision
465	                        || (file_revision > row.checkpoint_revision && state.active_turn.is_some())
466	                    {
467	                        return Err(ProjectionReset::RevisionMismatch);
468	                    }
469	                    file_revision > row.checkpoint_revision || row.checkpoint_json.is_none()
470	                }
471	            }
472	        };
473	        if needs_checkpoint {
474	            self.checkpoint(session_id, file_revision, file_snapshot)
475	                .map_err(|_| ProjectionReset::Faulted)?;
476	        }
477	
478	        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
479	        let tx = db.transaction().map_err(|_| ProjectionReset::Faulted)?;
480	        let row = load_row(&tx, &self.epoch, session_id)
481	            .map_err(|_| ProjectionReset::Faulted)?
482	            .ok_or(ProjectionReset::Faulted)?;
483	        if row.checkpoint_revision != file_revision {
484	            return Err(ProjectionReset::RevisionMismatch);
485	        }
486	        let state: FoldedState =
487	            serde_json::from_str(&row.state_json).map_err(|_| ProjectionReset::Faulted)?;
488	        let checkpoint = row
489	            .checkpoint_json
490	            .as_deref()
491	            .map(serde_json::from_str)
492	            .transpose()
493	            .map_err(|_| ProjectionReset::Faulted)?;
494	        let pending = query_frames(&tx, &self.epoch, session_id, row.checkpoint_seq, row.latest)
495	            .map_err(|_| ProjectionReset::Faulted)?;
496	        tx.commit().map_err(|_| ProjectionReset::Faulted)?;
497	        drop(db);
498	        let lease = self.issue_lease(session_id, row.latest);
499	        Ok(SessionProjection {
500	            version: 1,
501	            cursor: ProjectionCursor::new(&self.epoch, session_id, row.latest).to_string(),
502	            checkpoint_revision: row.checkpoint_revision,
503	            checkpoint,
504	            lease_id: lease.0,
505	            lease_expires_ms: lease.1,
506	            pending_events: pending,
507	            state: state.wire(),
508	        })
509	    }
