589	    fn issue_lease(&self, session_id: &str, min_seq: u64) -> (String, i64) {
590	        let now = Instant::now();
591	        let mut leases = self
592	            .leases
593	            .lock()
594	            .unwrap_or_else(|poison| poison.into_inner());
595	        leases.retain(|_, lease| lease.expires > now);
596	        if leases.len() >= MAX_LEASES {
597	            if let Some(oldest) = leases
598	                .iter()
599	                .min_by_key(|(_, lease)| lease.expires)
600	                .map(|(id, _)| id.clone())
601	            {
602	                leases.remove(&oldest);
603	            }
604	        }
605	        let id = Uuid::new_v4().to_string();
606	        let expires_ms = now_ms().saturating_add(self.lease_duration.as_millis() as i64);
607	        leases.insert(
608	            id.clone(),
609	            Lease {
610	                session_id: session_id.to_string(),
611	                min_seq,
612	                expires: now + self.lease_duration,
613	            },
614	        );
615	        (id, expires_ms)
616	    }
617	
618	    fn validate_lease(
619	        &self,
620	        session_id: &str,
621	        lease_id: &str,
622	        cursor_seq: u64,
623	    ) -> std::result::Result<(), ProjectionReset> {
624	        let now = Instant::now();
625	        let mut leases = self
626	            .leases
627	            .lock()
628	            .unwrap_or_else(|poison| poison.into_inner());
629	        let Some(lease) = leases.get(lease_id).cloned() else {
630	            return Err(ProjectionReset::InvalidLease);
631	        };
632	        if lease.expires <= now {
633	            leases.remove(lease_id);
634	            return Err(ProjectionReset::ExpiredLease);
635	        }
636	        if lease.session_id != session_id {
637	            return Err(ProjectionReset::LeaseSessionMismatch);
638	        }
639	        if cursor_seq < lease.min_seq {
640	            return Err(ProjectionReset::InvalidLease);
641	        }
642	        Ok(())
643	    }
