645	    fn renew_lease(
646	        &self,
647	        lease_id: &str,
648	        min_seq: u64,
649	    ) -> std::result::Result<(), ProjectionReset> {
650	        let now = Instant::now();
651	        let mut leases = self
652	            .leases
653	            .lock()
654	            .unwrap_or_else(|poison| poison.into_inner());
655	        let Some(lease) = leases.get_mut(lease_id) else {
656	            return Err(ProjectionReset::InvalidLease);
657	        };
658	        if lease.expires <= now {
659	            leases.remove(lease_id);
660	            return Err(ProjectionReset::ExpiredLease);
661	        }
662	        lease.min_seq = min_seq;
663	        lease.expires = now + self.lease_duration;
664	        Ok(())
665	    }
