758	fn query_frames(
759	    db: &Connection,
760	    epoch: &str,
761	    session_id: &str,
762	    after: u64,
763	    through: u64,
764	) -> Result<Vec<SessionProjectionFrame>> {
765	    let mut stmt = db.prepare(
766	        "SELECT seq,source,event_json FROM session_projection_events WHERE epoch=?1 AND session_id=?2 AND seq>?3 AND seq<=?4 ORDER BY seq ASC",
767	    )?;
768	    let rows = stmt.query_map(params![epoch, session_id, after, through], |row| {
769	        Ok((
770	            row.get::<_, u64>(0)?,
771	            row.get::<_, String>(1)?,
772	            row.get::<_, String>(2)?,
773	        ))
774	    })?;
775	    let mut frames = Vec::new();
776	    for row in rows {
777	        let (seq, source, event_json) = row?;
778	        frames.push(SessionProjectionFrame {
779	            cursor: ProjectionCursor::new(epoch, session_id, seq).to_string(),
780	            source: match source.as_str() {
781	                "agent" => SessionProjectionSource::Agent,
782	                "control" => SessionProjectionSource::Control,
783	                "checkpoint" => SessionProjectionSource::Checkpoint,
784	                _ => anyhow::bail!("unknown session projection source {source}"),
785	            },
786	            event: serde_json::from_str(&event_json)?,
787	        });
788	    }
789	    Ok(frames)
790	}
