800	fn session_hash(session_id: &str) -> String {
801	    let digest = Sha256::digest(session_id.as_bytes());
802	    digest[..8]
803	        .iter()
804	        .map(|byte| format!("{byte:02x}"))
805	        .collect()
806	}
