5409	/// Close out a finished prompt/turn on the request registry and announce the
5410	/// outcome on the legacy event bus. `origin` is `Some(EVENT_ORIGIN_AGENT)`
5411	/// when the caller is the agent-turn path (OCEAN-305): there the full stdout
5412	/// already streamed delta-by-delta on `/v1/agent/events`, so the legacy
5413	/// announcements here are agent-rail twins and are provenance-marked so a
5414	/// dual-rail client doesn't render the same turn twice. The legacy
5415	/// `/v1/prompt` / `/v1/requests` paths pass `None` — for them these
5416	/// announcements are the only delivery and must render normally.
5417	async fn record_prompt_result(
5418	    state: &AppState,
5419	    request_id: RequestId,
5420	    res: &ocean_core::PromptResponse,
5421	    origin: Option<&'static str>,
5422	) {
5423	    let desired_state = if res.ok {
5424	        RequestState::Completed
5425	    } else {
5426	        RequestState::Errored
5427	    };
5428	    let message = if res.ok {
5429	        "prompt completed".to_string()
5430	    } else {
5431	        res.stderr.clone()
5432	    };
5433	
5434	    let final_state = update_request_finished(
5435	        &state.requests,
5436	        request_id,
5437	        res.session_id,
5438	        desired_state,
5439	        message,
5440	    )
5441	    .await;
5442	
5443	    match final_state {
5444	        Some(RequestState::Completed) => {
5445	            if !res.stdout.trim().is_empty() {
5446	                emit_with_origin(
5447	                    &state.events,
5448	                    res.session_id,
5449	                    Some(request_id),
5450	                    None,
5451	                    origin,
5452	                    OceanEvent::AssistantDelta {
5453	                        text: res.stdout.clone(),
5454	                    },
5455	                );
5456	            }
5457	            emit_with_origin(
5458	                &state.events,
5459	                res.session_id,
5460	                Some(request_id),
5461	                None,
5462	                origin,
5463	                OceanEvent::TurnFinished {
5464	                    ok: true,
5465	                    wall_ms: res.wall_ms,
5466	                },
5467	            );
5468	        }
5469	        Some(RequestState::Errored) => {
5470	            emit_with_origin(
5471	                &state.events,
5472	                res.session_id,
5473	                Some(request_id),
5474	                None,
5475	                origin,
5476	                OceanEvent::Error {
5477	                    message: res.stderr.clone(),
5478	                },
5479	            );
5480	        }
5481	        Some(RequestState::Cancelled) => {
5482	            emit_with_origin(
5483	                &state.events,
5484	                res.session_id,
5485	                Some(request_id),
5486	                None,
5487	                origin,
